namespace sv_2fc3c4f75a1d461085377dae1049eac2.Services;

public class WarehouseInfo
{
    public string Id { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
}

/// <summary>
/// Scoped service that holds the currently selected warehouse for a single user circuit.
/// Components subscribe to OnChange to react when the warehouse selection changes.
/// </summary>
public class WarehouseState
{
    private string _currentWarehouseId = "wh-1";

    public static IReadOnlyList<WarehouseInfo> AvailableWarehouses { get; } =
    [
        new() { Id = "wh-1", Name = "Warehouse A — East" },
        new() { Id = "wh-2", Name = "Warehouse B — West" },
        new() { Id = "wh-3", Name = "Warehouse C — Central" },
    ];

    public string CurrentWarehouseId => _currentWarehouseId;

    public string CurrentWarehouseName =>
        AvailableWarehouses.FirstOrDefault(w => w.Id == _currentWarehouseId)?.Name ?? "Unknown";

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

namespace sv_2fc3c4f75a1d461085377dae1049eac2.Services;

/// <summary>
/// Scoped service that manages low-stock alert polling for the current user circuit.
/// Multiple components subscribe to OnAlertCountChanged to stay synchronized.
/// Polling is controlled by StartPolling/StopPolling — only active when the dashboard is visible.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseState _warehouseState;
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;

    public int CurrentAlertCount { get; private set; }

    public event Action? OnAlertCountChanged;

    public InventoryAlertService(WarehouseState warehouseState)
    {
        _warehouseState = warehouseState;
    }

    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulates a database query — returns a random number between 0 and 15.
        return Task.FromResult(_random.Next(0, 16));
    }

    public void StartPolling()
    {
        _subscriberCount++;
        if (_subscriberCount > 1) return; // Already polling

        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(_cts.Token);
    }

    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount > 0) return; // Other subscribers still active

        _cts?.Cancel();
        _timer?.Dispose();
        _timer = null;
        _cts?.Dispose();
        _cts = null;
    }

    /// <summary>
    /// Triggers an immediate refresh and notifies all subscribers.
    /// Called when the warehouse changes so counts update right away.
    /// </summary>
    public async Task RefreshAsync()
    {
        CurrentAlertCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        OnAlertCountChanged?.Invoke();
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Do an initial fetch immediately
        await RefreshAsync();

        while (!ct.IsCancellationRequested)
        {
            try
            {
                if (_timer is null || !await _timer.WaitForNextTickAsync(ct))
                    break;

                CurrentAlertCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
                OnAlertCountChanged?.Invoke();
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _timer?.Dispose();
        _cts?.Dispose();
    }
}

