        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Warehouse ID</h5>
                <p class="font-monospace">@WarehouseState.CurrentWarehouseId</p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Status</h5>
                <p>
                    @if (_isPolling)
                    {
                        <span class="badge bg-success">Live</span>
                        <span class="text-muted ms-2">Polling active</span>
